(() => {
'use strict';
const $=id=>document.getElementById(id), A=v=>Array.isArray(v)?v:[], C=v=>String(v??'').trim(), shuffle=a=>[...a].sort(()=>Math.random()-.5);
const R={P3:1,P4:2,P5:3}, KEY='APLUS_AI_TUTOR_STUDENT_V6';
const db={
 p3:typeof APLUS_AI_DB_V1_VOCABULARY_RICH_P3!=='undefined'?A(APLUS_AI_DB_V1_VOCABULARY_RICH_P3):[],
 p45:typeof APLUS_AI_DB_V1_VOCABULARY_RICH_P45!=='undefined'?A(APLUS_AI_DB_V1_VOCABULARY_RICH_P45):[],
 conf:typeof APLUS_AI_DB_V1_VOCABULARY_CONFUSABLES_P3P5_BATCH01!=='undefined'?A(APLUS_AI_DB_V1_VOCABULARY_CONFUSABLES_P3P5_BATCH01):[],
 grammar:typeof APLUS_AI_DB_V1_GRAMMAR_LARGE_P3P5_BATCH01!=='undefined'?A(APLUS_AI_DB_V1_GRAMMAR_LARGE_P3P5_BATCH01):[]
};
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch(e){};state=state||{version:6,level:'P3',questions:0,correct:0,skills:{},mistakes:[],history:[]};
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const rank=r=>{let x=C(r.level).toUpperCase();return x.includes('P3')?1:x.includes('P4')?2:x.includes('P5')?3:2};
const eligible=a=>{let n=R[state.level]||1;return a.filter(r=>Math.abs(rank(r)-n)<=1)};
const esc=x=>C(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const escRe=s=>C(s).replace(/[.*+?^${}()|[\\]\\]/g,'\\$&');
function skill(s){return state.skills[s]||{correct:0,total:0,mastery:0,lastWrong:0,streak:0}}
function mark(s,ok){let x=skill(s);x.total++;if(ok){x.correct++;x.streak++}else{x.lastWrong=Date.now();x.streak=0}x.mastery=Math.round(x.correct/x.total*100);state.skills[s]=x}
function findForm(sentence,word){let base=C(word);if(!base||!sentence)return null;let candidates=[base,base+'s',base+'ed',base+'ing',base.endsWith('e')?base.slice(0,-1)+'ing':'',base.endsWith('y')?base.slice(0,-1)+'ies':''];for(const f of [...new Set(candidates)].sort((a,b)=>b.length-a.length)){if(!f)continue;let m=C(sentence).match(new RegExp('\\b'+escRe(f)+'\\b','i'));if(m)return m[0]}return null}
function distractors(answer,rec,pool){let pos=C(rec.partOfSpeech||rec.wordClass||'').toLowerCase(),candidates=pool.filter(x=>x!==rec&&C(x.word).toLowerCase()!==C(rec.word).toLowerCase());if(pos){let same=candidates.filter(x=>C(x.partOfSpeech||x.wordClass||'').toLowerCase()===pos);candidates=[...same,...candidates]}let out=[],seen=new Set();for(const x of candidates){let w=C(x.word);if(!w||w.toLowerCase()===answer.toLowerCase()||seen.has(w.toLowerCase()))continue;seen.add(w.toLowerCase());out.push(w);if(out.length===3)break}return out}
function vocab(){let pool=eligible([...db.p3,...db.p45]),out=[];for(const r of shuffle(pool)){let word=C(r.word),ex=C(A(r.examples)[0]),form=findForm(ex,word);if(!word||!ex||!form)continue;let prompt=ex.replace(new RegExp('\\b'+escRe(form)+'\\b','i'),'_____');if(prompt===ex||!prompt.includes('_____'))continue;let ds=distractors(form,r,pool);if(ds.length<3)continue;out.push({id:'v:'+r.id,skill:'Vocabulary',topic:word,prompt,answer:form,options:shuffle([form,...ds]),explain:'The sentence needs “'+form+'”. '+C(r.definition),difficulty:Number(r.difficulty)||2});if(out.length>=40)break}return out}
const G={'common nouns':['There are _____ books on the shelf.',['three','a','much','one'],'three'],'pronouns':['Mum gave the book to _____.',['me','I','my','mine'],'me'],'determiners':['_____ apples are on the table.',['These','This','That','A'],'These'],'articles':['She ate _____ orange after lunch.',['an','a','the','some'],'an'],'subject-verb agreement':['The box of pencils _____ on the table.',['is','are','be','am'],'is'],'present simple':['Every morning, Amir _____ to school.',['walks','walk','walking','walked'],'walks'],'present continuous':['Look! The children _____ football.',['are playing','play','played','have played'],'are playing'],'past simple':['Yesterday, we _____ to the museum.',['went','go','gone','going'],'went'],'prepositions of time':['The test starts _____ Monday.',['on','at','in','by'],'on'],'conjunctions':['It was raining, _____ we stayed indoors.',['so','but','because','unless'],'so'],'past continuous':['I _____ dinner when the phone rang.',['was eating','ate','am eating','have eaten'],'was eating'],'present perfect':['She has _____ her project already.',['finished','finish','finishing','finishes'],'finished'],'modal verbs':['You _____ wear your seat belt.',['must','must to','musts','must wearing'],'must'],'adjectives':['This puzzle is _____ than the last one.',['more difficult','most difficult','difficultest','more difficulter'],'more difficult'],'adverbs':['The girl sang _____.',['beautifully','beautiful','beauty','beautify'],'beautifully'],'prepositions':['The cat jumped _____ the box.',['into','at','on','by'],'into'],'relative clauses':['The boy _____ won the race is my friend.',['who','which','where','what'],'who'],'reported speech':['He said that he _____ tired.',['was','is','were','be'],'was'],'conditional sentences':['If it _____, we will stay indoors.',['rains','will rain','rained','raining'],'rains'],'active and passive voice':['The cake _____ by Mum yesterday.',['was made','was make','made','is making'],'was made'],'gerunds and infinitives':['I enjoy _____ storybooks.',['reading','to read','read','reads'],'reading'],'quantifiers':['There is _____ water left.',['a little','a few','many','few'],'a little'],'possessives':['This is _____ bag.',['Sarah’s','Sarah','Sarahs','Sarahs’'],'Sarah’s'],'question forms':['Where _____ you going?',['are','is','do','did'],'are'],'there is and there are':['_____ three apples in the basket.',['There are','There is','There be','There has'],'There are'],'negative sentences':['She does not _____ coffee.',['drink','drinks','drank','drinking'],'drink'],'can and cannot':['He can _____ very fast.',['run','runs','running','to run'],'run'],'frequency adverbs':['She _____ walks to school.',['usually','usual','use','used'],'usually'],'adjective order':['She wore a _____ dress.',['beautiful red','red beautiful','beautifully red','red beautifully'],'beautiful red'],'comparative adjectives':['My bag is _____ than yours.',['heavier','heaviest','heavy','more heavy'],'heavier'],'superlative adjectives':['Ali is the _____ runner in the class.',['fastest','faster','most fast','fast'],'fastest'],'infinitive of purpose':['I went to the library _____ a book.',['to borrow','for borrow','borrowing','borrowed'],'to borrow'],'zero conditional':['If you heat ice, it _____.',['melts','will melt','melted','melting'],'melts'],'reported questions':['He asked where I _____.',['lived','did I live','do I live','am I living'],'lived'],'unless':['Unless you hurry, you _____ the bus.',['will miss','missed','are miss','will missed'],'will miss'],'passive':['English _____ in many countries.',['is spoken','is speak','speaks','is speaking'],'is spoken'],'although':['_____ he was tired, he continued working.',['Although','Despite','Because of','Unless'],'Although'],'because':['He stayed home _____ he was ill.',['because','despite','although','unless'],'because'],'parallel structure':['She likes reading, swimming, and _____.',['cycling','to cycle','cycle','cycled'],'cycling'],'irregular plural nouns':['The farmer has three _____.',['children','childs','child','childes'],'children'],'possessive nouns':['This is the _____ bicycle.',['girl’s','girls','girls’','girl'],'girl’s'],'object pronouns':['Dad called Sam and _____.',['me','I','my','mine'],'me'],'countable and uncountable nouns':['We need _____ information before deciding.',['more','many','a few','few'],'more'],'few and little':['There are _____ students absent today.',['a few','a little','much','little'],'a few'],'as as':['The new bag is as _____ as the old one.',['heavy','heavier','heaviest','more heavy'],'heavy']};
function grammar(){let out=[];for(const r of eligible(db.grammar)){let text=(C(r.topic)+' '+C(r.focus)+' '+A(r.skills).join(' ')).toLowerCase(),key=Object.keys(G).find(k=>text.includes(k.toLowerCase()));if(!key)continue;let g=G[key];if(g[1].length!==4)continue;let q={id:'g:'+r.id,skill:'Grammar',topic:r.topic,prompt:g[0],options:shuffle(g[1]),answer:g[2],explain:C(A(r.rules)[0])||'Choose the form that matches the sentence.',difficulty:Number(r.difficulty)||2};if(!out.some(x=>x.prompt===q.prompt))out.push(q)}return shuffle(out)}
function confusables(){let out=[];for(const r of shuffle(eligible(db.conf))){let pair=A(r.pair).map(C).filter(Boolean),cues=A(r.cue).map(C).filter(Boolean);if(pair.length!==2)continue;for(const cue of cues){let ans=pair.find(w=>new RegExp('\\b'+escRe(w)+'\\b','i').test(cue));if(!ans)continue;let prompt=cue.replace(new RegExp('\\b'+escRe(ans)+'\\b','i'),'_____');if(!prompt.includes('_____'))continue;let other=pair.find(w=>w!==ans);if(!other)continue;out.push({id:'c:'+r.id+':'+ans,skill:'Confusables',topic:pair.join(' / '),prompt,answer:ans,options:shuffle([ans,other]),explain:C(r.rule)||C(r.mistake)||'Use the word that fits the meaning and context.',difficulty:rank(r)});break}}return out}
function allQuestions(){return shuffle([...vocab(),...grammar(),...confusables()])}
function review(){let ms=state.mistakes||[],all=allQuestions(),exact=all.filter(q=>ms.some(m=>m.baseId===q.id));return shuffle(exact.length?exact:all).slice(0,10)}
let session={list:[],i:0,mode:'',correct:0,answered:0};
function build(mode){let all=mode==='grammar'?grammar():mode==='review'?review():mode==='mixed'?allQuestions():shuffle([...vocab(),...confusables()]);session={list:all.slice(0,mode==='mixed'?12:10),i:0,mode,correct:0,answered:0};render()}
function resultMessage(p){if(p===0)return ['Let’s review this together.','You found this session difficult. We’ll slow down, review the key ideas, and practise them step by step.'];if(p<40)return ['Let’s slow down and rebuild the basics.','You made several mistakes. We’ll focus on the skills that need the most support before moving to harder questions.'];if(p<70)return ['You are making progress.','Some skills still need more practice. Your Tutor Brain has marked the areas that need attention.'];if(p<90)return ['Good progress. Keep practising.','You understand many of the key ideas. More consistent practice will help strengthen them.'];return ['Excellent work.','You showed strong understanding in this session. Your Tutor Brain can now introduce more varied and challenging practice.']}
function finish(){let total=session.answered,p=total?Math.round(session.correct/total*100):0,m=resultMessage(p),wrong=(state.history||[]).slice(0,session.answered).filter(h=>!h.ok).length;$('quizLabel').textContent='SESSION COMPLETE';$('questionProgress').textContent='Tutor Brain updated';$('questionArea').innerHTML='<div class="empty-quiz"><div class="empty-icon">'+(p>=70?'✓':'!')+'</div><h3>'+esc(m[0])+'</h3><div class="session-score"><strong>'+p+'%</strong><span>'+session.correct+' of '+total+' correct</span></div><p>'+esc(m[1])+'</p><div class="session-next"><b>Next step</b><span>'+(wrong?'Your mistakes are in Smart Review. Start recovery practice before moving to harder questions.':'Your next session can introduce a new skill or a higher challenge.')+'</span></div>'+(wrong?'<div class="feedback-actions"><button class="next-btn" id="reviewNow" type="button">Review my mistakes →</button></div>':'')+'</div>';if($('reviewNow'))$('reviewNow').onclick=()=>build('review');update()}
function render(){let q=session.list[session.i];if(!q){finish();return}$('quizLabel').textContent=q.skill.toUpperCase();$('questionProgress').textContent='Question '+(session.i+1)+' of '+session.list.length+' · '+state.level;$('questionArea').innerHTML='<div class="question-text">'+esc(q.prompt)+'</div><div class="options">'+q.options.map((o,i)=>'<button class="option-btn" data-v="'+esc(o)+'" type="button"><b>'+String.fromCharCode(65+i)+'.</b> '+esc(o)+'</button>').join('')+'</div><div id="feedbackSlot"></div>';$('questionArea').querySelectorAll('.option-btn').forEach(b=>b.onclick=()=>answer(q,b))}
function answer(q,b){if(b.disabled)return;let ok=C(b.dataset.v).toLowerCase()===C(q.answer).toLowerCase();$('questionArea').querySelectorAll('.option-btn').forEach(x=>{x.disabled=true;if(C(x.dataset.v).toLowerCase()===C(q.answer).toLowerCase())x.classList.add('correct')});if(!ok)b.classList.add('wrong');state.questions++;if(ok){state.correct++;session.correct++}session.answered++;mark(q.skill,ok);if(!ok)state.mistakes=[{baseId:q.id,skill:q.skill,topic:q.topic,answer:q.answer,prompt:q.prompt,at:Date.now()},...(state.mistakes||[]).filter(x=>x.baseId!==q.id)].slice(0,50);else state.mistakes=(state.mistakes||[]).filter(x=>x.baseId!==q.id);state.history.unshift({id:q.id,ok,skill:q.skill,topic:q.topic,at:Date.now()});state.history=state.history.slice(0,200);save();let text=ok?'Correct. You identified the form or meaning that fits the sentence.':'Not correct yet. The answer is “'+q.answer+'”. Read the sentence again and look for the grammar or meaning clue.';$('feedbackSlot').innerHTML='<div class="feedback '+(ok?'feedback-good':'feedback-fix')+'"><b>'+(ok?'Correct!':'Let’s learn from this.')+'</b><br>'+esc(text)+'<br><small>'+esc(q.explain)+'</small></div><div class="feedback-actions"><button class="next-btn" id="nextQuestion" type="button">'+(session.i+1===session.list.length?'See session result':'Next question')+' →</button></div>';$('nextQuestion').onclick=()=>{session.i++;render()};update()}
function update(){$('statQuestions').textContent=state.questions;$('statAccuracy').textContent=state.questions?Math.round(state.correct/state.questions*100)+'%':'—';let vals=Object.values(state.skills).filter(x=>x.total);$('statMastery').textContent=vals.length?Math.round(vals.reduce((a,x)=>a+x.mastery,0)/vals.length)+'%':'0%';$('statReview').textContent=(state.mistakes||[]).length;$('dataStatus').textContent='Tutor Brain V6 ready · '+state.level;$('coachMessage').textContent=state.questions?'Your recent results are shaping the next practice.':'Let’s begin with one clear step.';let names=['Vocabulary','Grammar','Confusables'];$('skillsList').innerHTML=names.map(s=>{let x=skill(s);return '<div class="skill-row"><div class="skill-head"><span>'+s+'</span><span>'+x.mastery+'%</span></div><div class="bar"><span style="width:'+x.mastery+'%"></span></div></div>'}).join('');$('reviewList').innerHTML=(state.mistakes||[]).length?state.mistakes.slice(0,3).map(x=>'<div class="review-item"><span class="dot"></span><div><b>'+esc(x.skill)+'</b><small>'+esc(x.topic||'Review needed')+'</small></div></div>').join(''):'<div class="review-item"><span class="dot"></span><div><b>No urgent review item.</b><small>Keep practising to build your profile.</small></div></div>';$('pathList').innerHTML='<div class="path-item"><span class="dot"></span><div><b>1. Understand</b><small>Read the sentence and identify the clue.</small></div></div><div class="path-item"><span class="dot"></span><div><b>2. Recover</b><small>Review mistakes with guided practice.</small></div></div><div class="path-item"><span class="dot"></span><div><b>3. Transfer</b><small>Apply the skill in a new context.</small></div></div>'}
document.querySelectorAll('.level-btn').forEach(b=>b.onclick=()=>{state.level=b.dataset.level;save();document.querySelectorAll('.level-btn').forEach(x=>x.classList.toggle('active',x===b));update()});document.querySelectorAll('.practice-card').forEach(b=>b.onclick=()=>{build(b.dataset.mode);$('quizCard').scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('.tutor-actions button').forEach(b=>b.onclick=()=>{let a=b.dataset.action;if(a==='easier')build('review');else if(a==='another')build('vocabulary');else if(a==='challenge')build('mixed');else{let m=(state.mistakes||[])[0];alert(m?'Let’s review '+m.topic+'. Expected answer: '+m.answer+'.':'Complete a question first and the Tutor will use your mistake to guide review.')}});$('closeQuiz').onclick=()=>{$('questionArea').innerHTML='<div class="empty-quiz"><div class="empty-icon">✦</div><h3>Your next question is waiting.</h3><p>Choose a practice mode above.</p></div>'};$('resetBtn').onclick=()=>{if(confirm('Reset this Tutor Brain profile and all local learning data?')){localStorage.removeItem(KEY);location.reload()}};update();
})();
